/* @autogenerated */
import { TestBed } from '@angular/core/testing';
import { ActivatedRoute, Router } from '@angular/router';
import { of } from 'rxjs';
import { UnauthorizedComponent } from './unauthorized.component';
import { AppStateService } from '@shared/context/state/app-state.service';

describe('UnauthorizedComponent', () => {
  it('redirects to returnUrl when authenticated', () => {
    const router = {
      navigateByUrl: jasmine.createSpy('navigateByUrl'),
      navigate: jasmine.createSpy('navigate'),
    } as unknown as Router;

    const route = {
      snapshot: {
        queryParamMap: {
          get: (key: string) => (key === 'returnUrl' ? '/target' : null),
        },
      },
    } as unknown as ActivatedRoute;

    const state = {
      language: of('en'),
      tenant: of('main'),
      userInfo: { main: of({ authenticated: true }) },
    } as unknown as AppStateService;

    TestBed.configureTestingModule({
      imports: [UnauthorizedComponent],
      providers: [
        { provide: Router, useValue: router },
        { provide: ActivatedRoute, useValue: route },
        { provide: AppStateService, useValue: state },
      ],
    });

    TestBed.createComponent(UnauthorizedComponent);

    expect(router.navigateByUrl).toHaveBeenCalledWith('/target');
  });

  it('redirects to language and tenant when no returnUrl', () => {
    const router = {
      navigateByUrl: jasmine.createSpy('navigateByUrl'),
      navigate: jasmine.createSpy('navigate'),
    } as unknown as Router;

    const route = {
      snapshot: {
        queryParamMap: {
          get: () => null,
        },
      },
    } as unknown as ActivatedRoute;

    const state = {
      language: of('es'),
      tenant: of('main'),
      userInfo: { main: of({ authenticated: true }) },
    } as unknown as AppStateService;

    TestBed.configureTestingModule({
      imports: [UnauthorizedComponent],
      providers: [
        { provide: Router, useValue: router },
        { provide: ActivatedRoute, useValue: route },
        { provide: AppStateService, useValue: state },
      ],
    });

    TestBed.createComponent(UnauthorizedComponent);

    expect(router.navigate).toHaveBeenCalledWith(['es', 'main']);
  });
});
